import { records} from '../records.js'


export function getImage(name=0) {


    let record_type = "ImageObject"
     if (!Number.isNaN(name)) {
        name = record_type + String(name)
    }

    let record_id = "https://www.testrecord.com/" + name + "#" + record_type

    let record = {
        "@type": record_type,
        "@id": record_id,
        "contentUrl": "https://placehold.co/600x400"
    }

   


    return record


}